-- Public destination content is separate from dated trip operations and private records.
CREATE TABLE destinations (id TEXT PRIMARY KEY REFERENCES opportunities(id), slug TEXT NOT NULL UNIQUE, title TEXT NOT NULL, location TEXT NOT NULL, eyebrow TEXT NOT NULL DEFAULT '', summary TEXT NOT NULL DEFAULT '', introduction TEXT NOT NULL DEFAULT '', service TEXT NOT NULL DEFAULT '', partners TEXT NOT NULL DEFAULT '', focus TEXT NOT NULL DEFAULT '', setting TEXT NOT NULL DEFAULT '', notes TEXT NOT NULL DEFAULT '', dates_text TEXT NOT NULL DEFAULT '', image_url TEXT NOT NULL DEFAULT '', image_alt TEXT NOT NULL DEFAULT '', image_credit TEXT NOT NULL DEFAULT '', image_key TEXT, image_type TEXT, status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','archived')), sort_order INTEGER NOT NULL DEFAULT 0, revision INTEGER NOT NULL DEFAULT 1, updated_at TEXT NOT NULL);
CREATE TRIGGER destinations_sync_insert AFTER INSERT ON destinations BEGIN UPDATE opportunities SET title=NEW.title,location=NEW.location,active=(NEW.status='published'),sort_order=NEW.sort_order,updated_at=NEW.updated_at WHERE id=NEW.id; END;
CREATE TRIGGER destinations_sync_update AFTER UPDATE ON destinations BEGIN UPDATE opportunities SET title=NEW.title,location=NEW.location,active=(NEW.status='published'),sort_order=NEW.sort_order,updated_at=NEW.updated_at WHERE id=NEW.id; END;
INSERT INTO destinations(id,slug,title,location,eyebrow,summary,introduction,service,partners,focus,setting,notes,dates_text,image_url,image_alt,image_credit,status,sort_order,updated_at) VALUES('trip-athens','athens','Athens, Greece','Athens, Greece','Presence among the crossroads','Walk alongside ministries serving neighbors experiencing homelessness, displacement, and exploitation.','Athens is a city of ancient beauty and present-day complexity—a crossroads for residents, refugees, travelers, and people rebuilding their lives.','Teams may support outreach walks, hospitality, meal or supply distribution, children and family activities, prayer, facilities projects, and other needs identified by local leaders.','New Start Ministries — Supporting practical next steps and renewed hope.
Athens Homeless Walks Ministries — Meeting neighbors on the street with dignity, consistency, and care.
Glocal Cafe — Creating hospitality and connection across cultures.
Additional local ministries — Serving people experiencing homelessness, refugees, and survivors of human trafficking.','Homelessness, refugee care & anti-trafficking support','Urban ministry','Specific activities and ministry partners will be confirmed before registration opens.','June 26–July 2, 2027 Scheduled Spots available · Pastoral planning trip
July 10–20, 2027 Team confirmed Additional spots available','https://christiansteps.net/Images/tripmap/2026-06-4_athens_3.jpg','Hope Sojourns team members gathered on Mars Hill in Athens','','published',10,strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT INTO destinations(id,slug,title,location,eyebrow,summary,introduction,service,partners,focus,setting,notes,dates_text,image_url,image_alt,image_credit,status,sort_order,updated_at) VALUES('trip-kenya','kenya','Kenya','Kenya','Safety, education & a future','Encourage a place of safety, education, and possibility for girls.','This developing journey is centered on encouragement, education, and practical support for girls building lives of safety and possibility.','Potential team roles may include educational activities, mentoring support, creative programs, facilities projects, staff encouragement, and supplies requested by the home’s leadership.','The Jerri Savuto Home for Girls — A place of safety and opportunity for girls affected by harmful practices and early marriage.','Girls’ safety, education & encouragement','Residential and community ministry','Images are representative of education in Kenya and do not depict residents of the Jerri Savuto Home.','','/assets/kenya.jpg','Students in Kenya gathered outdoors','','published',20,strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT INTO destinations(id,slug,title,location,eyebrow,summary,introduction,service,partners,focus,setting,notes,dates_text,image_url,image_alt,image_credit,status,sort_order,updated_at) VALUES('trip-belize','belize','Belize','Belize','Rooted in the rainforest','Serve with a rainforest ministry rooted in relationship and community.','Beyond the coastline, Belize’s rainforest communities are places of remarkable beauty, deep relationship, and practical ministry opportunity.','Teams may assist with community projects, children’s activities, ministry programs, facilities work, hospitality, and other priorities shaped by Andy Ministries.','Andy Ministries — Serving people and communities in the Belizean rainforest through long-term local relationships.','Community partnership & practical service','Rainforest communities','Trip scope, accommodations, travel requirements, and service activities are still in development.','March or April 2027 Planning','/assets/belize-cotton-wood-lodge-loft.png','The loft at Cotton Wood Lodge in Belize where mission teams will stay','','published',30,strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT INTO destinations(id,slug,title,location,eyebrow,summary,introduction,service,partners,focus,setting,notes,dates_text,image_url,image_alt,image_credit,status,sort_order,updated_at) VALUES('trip-nice','nice','Nice, France','Nice, France','Joyful ministry on the Riviera','Help create joyful, welcoming Bible experiences for children and families.','Nice is known for its beauty, but every community also needs belonging, encouragement, and spaces where children can encounter faith with joy.','Team members may help prepare and lead children’s activities, music, crafts, games, storytelling, logistics, hospitality, and support for local volunteers.','International VBS Ministries — Helping churches and communities create engaging, culturally thoughtful Bible experiences for children.','Children, families & Vacation Bible School','Urban and church ministry','Program themes, language needs, and final ministry locations will be confirmed with the host ministry.','July 15–26, 2027 Scheduled Spots available','/assets/nice-old-town-tile.png','A welcoming pedestrian street with cafes in Old Nice, France','','published',40,strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT INTO destinations(id,slug,title,location,eyebrow,summary,introduction,service,partners,focus,setting,notes,dates_text,image_url,image_alt,image_credit,status,sort_order,updated_at) VALUES('trip-arkansas','arkansas','Shephard of the Ozarks','Shephard of the Ozarks','Serve close to home','Support camp ministry and community needs near Marshall, Arkansas.','The Arkansas Ozarks offer a meaningful domestic mission setting where camp ministry and community service come together.','Potential work may include camp preparation, maintenance and beautification, children or youth programming, community projects, event support, and encouragement for local leaders.','Shephard of the Ozarks Camp — Supporting a place for faith, rest, formation, and outdoor community.
City of Marshall, Arkansas — Responding to practical community priorities through respectful local partnership.','Camp ministry & community service','Rural Arkansas','Project assignments will be based on current camp and community needs.','November 2027 Planning','/assets/soto-buffalo-conference-center.png','The Buffalo Conference Center at Shepherd of the Ozarks','','published',50,strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT INTO destinations(id,slug,title,location,eyebrow,summary,introduction,service,partners,focus,setting,notes,dates_text,image_url,image_alt,image_credit,status,sort_order,updated_at) VALUES('trip-mexico-city','mexico-city','Mexico City, Mexico','Mexico City, Mexico','A joint journey of practical care','Join Metro Relief of Dallas in supporting a sister ministry serving neighbors experiencing homelessness.','Hope Sojourns is preparing for a January 10–16, 2027 joint trip with Metro Relief of Dallas to support a sister ministry serving people experiencing homelessness in Mexico City.','Team members may support street outreach, meal or supply distribution, prayer, listening, conversation, and other practical needs identified by local ministry leaders.','Metro Relief of Dallas — Helping coordinate the joint team and connect Hope Sojourns with a sister ministry in Mexico City.
Sister ministry in Mexico City — Serving neighbors experiencing homelessness through trusted, ongoing local relationships.','Homeless ministry','Urban ministry','Costs, host-ministry details, travel requirements, and final team roles will be confirmed before registration opens.','January 10–16, 2027 Scheduled Interest conversations open','/assets/mexico-city.jpg','Palacio de Bellas Artes and the Mexico City skyline','Photo by Jeses via Wikimedia Commons , used under CC BY-SA 2.5 ; cropped for display. https://commons.wikimedia.org/wiki/File:Mexico_City_Palacio_de_bellas_artes.jpg','published',60,strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT INTO destinations(id,slug,title,location,eyebrow,summary,introduction,service,partners,focus,setting,notes,dates_text,image_url,image_alt,image_credit,status,sort_order,updated_at) VALUES('trip-future-journeys','others','Other Journeys','Domestic and international','The next place of service','Discover new opportunities as trusted ministry relationships and community partnerships develop.','Hope Sojourns is continuing to listen for trustworthy partners and meaningful places where a prepared team can serve well.','Possible destinations and service areas will be announced as relationships develop. We welcome conversations with churches, ministries, schools, and community organizations.','Developing partnerships — Future journeys will be built around local invitation, responsible leadership, and clearly defined needs.','New mission partnerships','Domestic and international','Have a ministry partnership in mind? Book a conversation and tell us about it.','','/assets/athens.jpg','A wide city view representing future Hope Sojourns destinations','','published',70,strftime('%Y-%m-%dT%H:%M:%fZ','now'));
